/**
 * Normalize any locale string into a canonical BCP-47 tag matching our dictionary.
 */
export function normalizeLocale(locale) {
  if (!locale || typeof locale !== 'string') return DEFAULT_LOCALE;
  const raw = locale.trim().replace(/_/g, '-');
  const lower = raw.toLowerCase();

  // Exact case match
  if (TRANSLATIONS[raw]) return raw;

  // Case-insensitive exact match
  for (const code of Object.keys(TRANSLATIONS)) {
    if (code.toLowerCase() === lower) return code;
  }

  // Common aliases & regional fallbacks
  if (lower.startsWith('pt')) {
    return lower === 'pt-pt' ? 'pt' : 'pt-BR';
  }
  if (lower.startsWith('es')) {
    return lower === 'es-es' ? 'es-ES' : 'es';
  }
  if (lower.startsWith('sv')) {
    return lower === 'sv-se' ? 'sv-SE' : 'sv';
  }
  if (lower.startsWith('ga')) {
    return lower === 'ga-ie' ? 'ga-IE' : 'ga';
  }
  if (lower.startsWith('nb') || lower.startsWith('nn') || lower === 'no') {
    return 'nb-NO';
  }
  if (lower.startsWith('zh')) {
    if (lower.includes('hant') || lower.includes('tw') || lower.includes('hk') || lower.includes('mo')) {
      return 'zh-TW';
    }
    return 'zh-CN';
  }
  if (lower.startsWith('en')) {
    return 'en-US';
  }

  // Base language prefix match (e.g. fr-CA -> fr, de-AT -> de)
  const base = lower.split('-')[0];
  for (const code of Object.keys(TRANSLATIONS)) {
    if (code.toLowerCase() === base) return code;
  }

  return DEFAULT_LOCALE;
}

/**
 * Resolve the active locale from explicit request, preferences, Gecko Services, or DOM/navigator.
 * Always falls back cleanly to 'en-US' (English).
 */
export function resolveLocale(requestedLocale = null, context = null) {
  if (requestedLocale && typeof requestedLocale === 'string') {
    return normalizeLocale(requestedLocale);
  }

  // 0. Environment variable override (e.g. in tests)
  try {
    if (typeof process !== 'undefined' && process.env && process.env.ARGON_LOCALE) {
      return normalizeLocale(process.env.ARGON_LOCALE);
    }
  } catch {}

  // 1. Gecko Services preferences / locale from context or global Services
  try {
    const services = context?.Services || (typeof Services !== 'undefined' ? Services : null);
    if (services) {
      if (services.prefs) {
        const userPref = services.prefs.getStringPref('argon.locale', '') ||
                         services.prefs.getStringPref('intl.locale.requested', '');
        if (userPref) return normalizeLocale(userPref);
      }
      if (services.locale?.appLocaleAsBCP47) {
        return normalizeLocale(services.locale.appLocaleAsBCP47);
      }
    }
  } catch {}

  // 2. DOM documentElement lang from context
  try {
    const doc = context?.document || (typeof document !== 'undefined' ? document : null);
    if (doc?.documentElement?.lang) {
      return normalizeLocale(doc.documentElement.lang);
    }
  } catch {}

  // 3. Window navigator language if context is a window
  try {
    const nav = context?.navigator;
    if (nav?.language) {
      return normalizeLocale(nav.language);
    }
  } catch {}

  return DEFAULT_LOCALE;
}

/**
 * Translate a key into the active or specified locale with parameter interpolation.
 * Falls back to English (en-US) if the key is missing in the target locale.
 */
export function t(key, params = null, locale = null, context = null) {
  const activeLocale = resolveLocale(locale, context);
  const dict = TRANSLATIONS[activeLocale] || TRANSLATIONS[DEFAULT_LOCALE];
  const fallbackDict = TRANSLATIONS[DEFAULT_LOCALE];

  let text = dict[key] !== undefined ? dict[key] : fallbackDict[key];
  if (text === undefined) {
    text = String(key);
  }

  if (params && typeof params === 'object') {
    text = text.replace(/\{([a-zA-Z0-9_-]+)\}/g, (match, paramName) => {
      return params[paramName] !== undefined ? String(params[paramName]) : match;
    });
  }

  return text;
}

/**
 * Create a bound translator instance for a given context and locale.
 */
export function createI18n(context = null, fixedLocale = null) {
  const getLocale = () => resolveLocale(fixedLocale, context);
  return {
    get locale() {
      return getLocale();
    },
    t(key, params = null) {
      return t(key, params, getLocale(), context);
    },
    applyToDOM(root = null) {
      return applyToDOM(root, getLocale(), context);
    },
  };
}

/**
 * Apply translations to DOM elements with data-i18n attributes.
 */
export function applyToDOM(root = null, locale = null, context = null) {
  const doc = root?.ownerDocument || (root && root.nodeType === 9 ? root : (typeof document !== 'undefined' ? document : null));
  if (!doc) return;
  const targetRoot = root || doc;
  const resolved = resolveLocale(locale, context || doc.defaultView);

  if (doc.documentElement) {
    doc.documentElement.lang = resolved;
    const meta = LOCALES[resolved];
    if (meta?.dir) {
      doc.documentElement.dir = meta.dir;
    }
  }

  // Text content
  const textElements = targetRoot.querySelectorAll ? targetRoot.querySelectorAll('[data-i18n]') : [];
  for (const el of textElements) {
    const key = el.getAttribute('data-i18n');
    if (key) {
      el.textContent = t(key, null, resolved, context);
    }
  }

  // ARIA labels
  const ariaElements = targetRoot.querySelectorAll ? targetRoot.querySelectorAll('[data-i18n-aria-label]') : [];
  for (const el of ariaElements) {
    const key = el.getAttribute('data-i18n-aria-label');
    if (key) {
      el.setAttribute('aria-label', t(key, null, resolved, context));
    }
  }

  // Titles
  const titleElements = targetRoot.querySelectorAll ? targetRoot.querySelectorAll('[data-i18n-title]') : [];
  for (const el of titleElements) {
    const key = el.getAttribute('data-i18n-title');
    if (key) {
      el.setAttribute('title', t(key, null, resolved, context));
    }
  }

  // Placeholders
  const placeholderElements = targetRoot.querySelectorAll ? targetRoot.querySelectorAll('[data-i18n-placeholder]') : [];
  for (const el of placeholderElements) {
    const key = el.getAttribute('data-i18n-placeholder');
    if (key) {
      el.setAttribute('placeholder', t(key, null, resolved, context));
    }
  }
}
